import{_ as i,a0 as s,w as a,s as u,ao as l,I as n,x as e,a1 as p,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const O=JSON.parse('{"title":"保持对云服务供应商选择的多样性 | LCTT x X-CMD","titleTemplate":false,"description":"保持对云服务供应商选择的多样性 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"保持对云服务供应商选择的多样性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"保持对云服务供应商选择的多样性 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20220509 Cloud service providers- How to keep your options open","title":"保持对云服务供应商选择的多样性","tag":"202312","desc":""},"relativePath":"202312/20220509 Cloud service providers- How to keep your options open.md","filePath":"[post].md"}'),d={name:"202312/20220509 Cloud service providers- How to keep your options open.md"};function f(m,t,T,k,S,x){const o=s("Link");return a(),u("div",null,[t[26]||(t[26]=l('<h1 id="保持对云服务供应商选择的多样性" tabindex="-1">保持对云服务供应商选择的多样性 <a class="header-anchor" href="#保持对云服务供应商选择的多样性" aria-label="Permalink to “保持对云服务供应商选择的多样性”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202312/17/223915neao8gei208poo8c.jpg" alt=""></p><blockquote><p>不论云服务的开放程度如何，你都能为自己的环境选择合适的方式。</p></blockquote><p>对于 Linux 用户来说，市场上有一种新型的电脑出现，我们称之为“云”。</p><p>如同你桌面上的个人电脑，背包里的笔记本电脑，或是你租用的虚拟私有服务器一样，你可以选择不同的云计算供应商。虽然品牌名称和你以往熟悉的硬件品牌不一致，但其核心概念是相同的。</p><p>要运行 Linux，你需要一台电脑。要在云上运行 Linux，你需要一个云服务供应商。就像你的电脑中的硬件和固件一样，你的计算堆栈可以使用多大的开源程度也是有区别的。</p><p>作为一个开源的用户，我更偏向于拥有尽量开放的计算集成环境。在对云计算市场进行详细的调研后，我形成了关于云服务供应商的三层观点。你可以根据这个体系作为指南，对你将选择的云供应商作出明确的决策。</p><h3 id="开放堆栈" tabindex="-1">开放堆栈 <a class="header-anchor" href="#开放堆栈" aria-label="Permalink to “开放堆栈”">​</a></h3><p>一个完全开放的云是从底层开始就建立在开源技术之上的云。由于云科技中有很大一部分从一开始就是开源的，因此技术层面的开放性堆栈并不难以实现。然而，也有云供应商以专有的方式重新发明轮子，这让用户很容易误入使用了许多封闭源码组件的云服务商的陷阱中。</p>',9)),n("p",null,[t[1]||(t[1]=e("如果你在寻找一个真正开放的云，那么你应该寻找一个提供 ",-1)),p(o,{href:"https://opensource.com/resources/what-is-openstack"},{default:r(()=>[...t[0]||(t[0]=[e("OpenStack",-1)])]),_:1}),t[2]||(t[2]=e(" 作为基础的云供应商。OpenStack 提供云的软件基础设施，包括通过 Neutron 实现的软件定义网络（SDN）、通过 Swift 实现的对象存储、身份和密钥管理、镜像服务等等。按照我的硬件电脑比喻，OpenStack 就是驱动云的“内核”。",-1))]),t[27]||(t[27]=n("p",null,"当然，我并不是字面上的意思，但如果你的云供应商运行 OpenStack，那相当于你可以直接到达堆栈的底部。从用户的角度看，OpenStack 是你的云存在并拥有文件系统、网络等的原因所在。",-1)),n("p",null,[t[4]||(t[4]=e("在 OpenStack 的主体上，可能有一个像 Horizon 或 Skyline 这样的网络用户界面，可能有像 ",-1)),p(o,{href:"https://cloud.redhat.com/?intcmp=7013a000002qLH8AAM"},{default:r(()=>[...t[3]||(t[3]=[e("OpenShift",-1)])]),_:1}),t[5]||(t[5]=e(" 或 OKD（并不是一个缩写，但前身是 OpenShift Origin）这样的额外组件。所有这些都是开源的，它们帮助你运行容器，这些容器是内嵌应用程序的极简 Linux 镜像。",-1))]),t[28]||(t[28]=l('<p>因为 OpenShift 和 OKD 不需要 OpenStack，这就构成了我对云世界的下一个视野级别。</p><h3 id="开放平台" tabindex="-1">开放平台 <a class="header-anchor" href="#开放平台" aria-label="Permalink to “开放平台”">​</a></h3><p>你并不总是可以选择你的云正在运行的堆栈。你的云可能运行的是 Azure、AWS，或者类似的东西，而不是 OpenStack。</p><p>这些就是云世界的“二进制碎片”。你对它们如何工作，或者为什么工作一无所知；你只知道你的云存在，并且有一个文件系统，一个网络堆栈，等等。</p><p>就像桌面计算一样，你可以在获得的服务器上运行一个“操作系统”。言下之意，有一种观点认为 OpenStack 本质上就是云计算的操作系统。然而，通常情况下，用户直接交互的是 OpenShift。</p><p>OpenShift 是一个你可以使用 Podman 和 Kubernetes 管理容器和 <ruby>容器荚<rt>Pod</rt></ruby> 的开源“桌面”或工作区。它让你在云上运行应用程序，就像你在笔记本电脑上启动一个应用一样。</p><h3 id="开放标准" tabindex="-1">开放标准 <a class="header-anchor" href="#开放标准" aria-label="Permalink to “开放标准”">​</a></h3><p>最后，同样重要的一点是，有些情况下你在选择云服务供应商上没有什么选择。你被放在一个运行着专有“内核”、专有“操作系统”的平台上，你能影响的只剩下你在那个环境里运行什么。</p><p>但掌握开源的力量，你就能建立你自己的平台。你可以选择在容器内部使用的组件。你可以，而且应该，围绕开源工具设计你的工作环境，因为这样一来，如果你有机会更换服务供应商，你可以将你的所有工作迁移到新的供应商那里。</p><p>这可能需要你自行实现一些在你当前受限（非开源）平台上已经内置的功能。例如，你的云供应商可能会用一个包含在他们平台“免费”提供的 API 管理系统或持续集成/持续交付（CI/CD）管道来吸引你，这需要你有清醒的认识。当一个非开放的应用被免费提供时，通常会以其他形式带来一些成本。其中一种成本是，一旦你开始在它的基础上构建，你会更加不愿意迁移，因为你会离开你已建立的一切。</p>',10)),n("p",null,[t[8]||(t[8]=e("你应当为自己重建这些封闭“特性”，并将其转化为开源服务。在容器中运行 ",-1)),p(o,{href:"https://opensource.com/article/19/9/intro-building-cicd-pipelines-jenkins"},{default:r(()=>[...t[6]||(t[6]=[e("Jenkins",-1)])]),_:1}),t[9]||(t[9]=e(" 和 ",-1)),p(o,{href:"https://www.apiman.io/latest/"},{default:r(()=>[...t[7]||(t[7]=[e("APIMan",-1)])]),_:1}),t[10]||(t[10]=e("。找出你的云提供商声称用专有代码解决的问题，然后使用开源解决方案来确保，当你离开寻找开放的供应商时，你可以迁移你已经构建的系统。",-1))]),t[29]||(t[29]=n("h3",{id:"开源计算",tabindex:"-1"},[e("开源计算 "),n("a",{class:"header-anchor",href:"#开源计算","aria-label":"Permalink to “开源计算”"},"​")],-1)),t[30]||(t[30]=n("p",null,"对于太多的人来说，云计算是一个开源居于次要地位的领域。实际上，开源在云上的重要性与它在你的个人电脑和驱动互联网的服务器上同样重要。",-1)),t[31]||(t[31]=n("p",null,"寻找开源的云服务。",-1)),t[32]||(t[32]=n("p",null,"当你受困于无法获取源代码的环境时，就肩负起在你的云内使用开源软件的责任吧。",-1)),t[33]||(t[33]=n("p",null,[n("em",null,"（题图：DA/9dc5a9d0-d664-492f-890a-b437ce39c4d6）")],-1)),t[34]||(t[34]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=e("via: ",-1)),p(o,{href:"https://opensource.com/article/22/5/cloud-service-providers-open"},{default:r(()=>[...t[11]||(t[11]=[e("https://opensource.com/article/22/5/cloud-service-providers-open",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=e("作者：",-1)),p(o,{href:"https://opensource.com/users/seth"},{default:r(()=>[...t[13]||(t[13]=[e("Seth Kenlon",-1)])]),_:1}),t[18]||(t[18]=e(" 选题：",-1)),p(o,{href:"https://github.com/lkxed"},{default:r(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),p(o,{href:"https://linux.cn/lctt/ChatGPT"},{default:r(()=>[...t[15]||(t[15]=[e("ChatGPT",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),p(o,{href:"https://github.com/wxy"},{default:r(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),p(o,{href:"https://linux.cn/"},{default:r(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const P=i(d,[["render",f]]);export{O as __pageData,P as default};
